window.AUTH=window.AUTH||{};window.AUTH["23-825"]={"d":"23-825","id":"2024/23-825","n":"Delligatti v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Salvatore Delligatti","date":"2024-08-08","url":"https://www.supremecourt.gov/DocketPDF/23/23-825/321972/20240808124108689_Delligatti%20-%20Merits%20Brief%20-%20RTF.pdf","side":"pet","n":32},{"k":"respondent","label":"Brief of respondent United States","date":"2024-09-30","url":"https://www.supremecourt.gov/DocketPDF/23/23-825/327160/20240930152003979_23-825bsUnitedStates.pdf","side":"res","n":74},{"k":"reply","label":"Reply of petitioner Salvatore Delligatti","date":"2024-10-30","url":"https://www.supremecourt.gov/DocketPDF/23/23-825/330653/20241030123857350_23-825%20--%20Delligatti%20-%20Reply%20Brief%20rtf.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us2r19_i42j.pdf","tr":true,"items":[{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"op":5,"sum":"The proximity and accessibility test for \"use\" is so broad that no independent role remains for \"carry.\" \"Use\" in Section 924(c)(1) requires more than proximity and accessibility that might embolden a defendant. It requires active employment of the firearm by the defendant, making the firearm an operative factor in relation to the predicate offense.","sumSrc":"Oyez","by":{"0":"12, 14, 15, 24, 30, 31","1":"19, 38, 39","2":"2, 3, 4, 8"}},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"0":"26, 27","1":"42, 43","2":"14"}},{"t":"case","label":"Borden v. United States","cite":"593 U.S. 420","y":2021,"id":"2020/19-5410","sc":1,"op":3,"ar":8,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"8, 12, 22-23, 29, 33-35, 39, 41-42","1":"6, 10, 19, 20, 32, 35, 37, 38, 46","2":"4, 7, 11, 12, 14, 16, 18, 20"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"op":1,"sum":"The Court held that, under 21 U.S.C. § 841(b) of the statute regarding drug-related deaths, an individual convicted of the death of another through the sale of drugs cannot be convicted of drug-induced homicide if multiple drugs are present in the deceased's system.","sumSrc":"Oyez","by":{"0":"13, 41","2":"10, 15"}},{"t":"case","label":"Campos-Chavez v. Garland","cite":"144 S. Ct. 1637","y":2024,"id":"2023/22-674","sc":1,"sum":"Because each of the aliens in this case received a proper notice for the removal hearings they missed and at which they were ordered removed from the United States, see 8 U. S. C. §1229(a)(2), they cannot seek rescission of their in absentia removal orders on the basis of defective notice under §1229a(b)(5)(C)(ii).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Chambers v. United States","cite":"555 U.S. 122","y":2009,"id":"2008/06-11206","sc":1,"sum":"The Court found that the \"failure to report\" crime does not satisfy the Armed Career Criminals Act's (ACCA) \"crime of violence\" definition.","sumSrc":"Oyez","by":{"0":"25","1":"43"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"op":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14, 25, 29, 42","2":"2, 10"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"op":10,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"0":"17, 19, 20, 22, 23, 33, 34, 38, 39","1":"10, 13, 14, 16, 17, 34, 36","2":"9"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"4, 25, 40, 41","2":"17"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"op":4,"ar":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"0":"4, 8, 15, 19, 20, 22, 23","1":"19, 37, 38","2":"3, 12"}},{"t":"case","label":"People v. Best","cite":"609 N.Y.S. 2d 478","y":1994,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.%202d/609/478/","op":1,"sum":"Upholding conviction of mother who “fail[ed] to seek medical attention for [her] boy”.","sumSrc":"brief:0","by":{"0":"18"}},{"t":"case","label":"People v. Steinberg","cite":"595 N.E.2d 845","y":1992,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/595/845/","op":2,"sum":"Upholding conviction of mother who “fail[ed] to seek medical attention for [her] boy”.","sumSrc":"brief:0","by":{"0":"18","1":"43"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that a criminal who trades his or her firearm for drugs \"uses\" it \"during and in relation to . . . [a] drug trafficking crime,\" which is within the bounds of the sentence enhancement. Justice O'Connor wrote that Congress intended to make the word \"use\" as broad as possible when it wrote the law.","sumSrc":"Oyez","by":{"0":"12, 15","1":"10, 18, 19","2":"2"}},{"t":"case","label":"Stokeling v. United States","cite":"586 U.S. 73","y":2019,"id":"2018/17-5554","sc":1,"op":16,"ar":7,"sum":"The Armed Career Criminal Act’s elements clause encompasses a robbery offense that, like Florida’s law, requires the criminal to overcome the victim’s resistance.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"8, 20, 21, 22, 33, 34, 37, 38","1":"32, 34, 35, 46","2":"7, 16, 18"}},{"t":"case","label":"(iii) Cases—Continued Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27","2":"16"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"op":33,"ar":8,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"0":"10, 12, 13, 20, 30, 31, 35-39","1":"9-13, 15-17, 19, 21, 32-36, 47","2":"1, 4, 6, 9, 10, 11"}},{"t":"case","label":"United States v. Davis","cite":"588 U.S. 445","y":2019,"id":"2018/18-431","sc":1,"op":3,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 5, 6, 25, 41, 42","1":"6, 30"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"sum":"The Court held 7-2 that the U.S. Code's section 3565 refers to the original sentence range set by U.S. Sentencing Guidelines. Therefore, the minimum revocation sentence for drug possession while on probation is one third the maximum of the Guidelines range of imprisonment; the maximum revocation sentence is the Guidelines maximum.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"sum":"Authored by Justice David Souter, the Court ruled that the standard of notice that the Court of Appeals employed was higher than the Constitution requires and too demanding.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"United States v. Laurent","cite":"33 F.4th 63","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/33/63/","by":{"0":"6"}},{"t":"case","label":"United States v. Ramirez","cite":"606 F.3d 396","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/606/396/","by":{"0":"41"}},{"t":"case","label":"United States v. Scott","cite":"990 F.3d 94","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/990/94/","op":2,"by":{"0":"6, 18, 42, 43","1":"9, 20, 21, 28, 47"}},{"t":"case","label":"United States v. Taylor","cite":"596 U.S. 845","y":2022,"id":"2021/20-1459","sc":1,"op":5,"sum":"Attempted Hobbs Act robbery does not qualify as a “crime of violence” under 18 U. S. C. §924(c)(3)(A) because no element of the offense requires proof that the defendant used, attempted to use, or threatened to use force.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5, 8, 16, 17, 41","1":"6, 8, 39","2":"8, 13, 18"}},{"t":"case","label":"United States v. Walker","cite":"442 F.3d 787","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/442/787/","by":{"0":"40"}},{"t":"case","label":"United States v. Williams","cite":"343 F.3d 432","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/343/432/","by":{"0":"41"}},{"t":"case","label":"Voisine v. United States","cite":"579 U.S. 686","y":2016,"id":"2015/14-10154","sc":1,"op":4,"ar":3,"sum":"The Court held that a reckless domestic violence assault qualifies as misdemeanor crime of domestic violence for the purpose of prohibiting firearm possession.","sumSrc":"Oyez","by":{"0":"12, 15, 16","1":"19, 32, 37","2":"4"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25, 26, 27"}},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","subs":["(a)"],"stext":{"head":"§16. Crime of violence defined","paras":[[0,"The term \"crime of violence\" means—"],[1,"(a) an offense that has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(b) any other offense that is a felony and that, by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/16?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§16. Crime of violence defined","tname":"Crimes and Criminal Procedure","by":{"0":"15, 19"}},{"t":"law","label":"Pub. L. No. 90-618","url":"https://www.govinfo.gov/link/statute/82/1213","by":{"0":"25"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1837","by":{"0":"28,29"}},{"t":"law","label":"Pub. L. No. 105-386","url":"https://www.govinfo.gov/link/plaw/105/public/386","by":{"0":"14"}},{"t":"case","label":"Allen v. United States","cite":"2023 WL 4145321","y":2023,"court":"6th Cir. June 23","by":{"1":"42"}},{"t":"case","label":"Association for Molecular Pathology v. Myriad Genetics, Inc.","cite":"569 U.S. 576","y":2013,"id":"2012/12-398","sc":1,"sum":"The Court held that naturally occurring genes cannot be patented, but a creation of a new product in a lab could be patented.","sumSrc":"Oyez","by":{"1":"22","2":"5"}},{"t":"case","label":"Astor v. Merritt","cite":"111 U.S. 202","y":1884,"id":"scdb/1883-211","sc":1,"sum":"Customs Duties — Wearing Apparel.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Caraco Pharm. Labs., Ltd. v. Novo Nordisk A/S","cite":"566 U.S. 399","y":2012,"id":"2011/10-844","sc":1,"sum":"The Court held that counterclaims that challenge unpatented uses of generic drugs, even if other approved uses are still under patent, are allowable under the Hatch-Waxman Act.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Commonwealth v. Hall","cite":"78 N.E.2d 644","y":1948,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/78/644/","op":1,"by":{"1":"28"}},{"t":"case","label":"Davis v. Commonwealth","cite":"335 S.E.2d 375","y":1985,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/335/375/","by":{"1":"28","2":"20"}},{"t":"case","label":"Faunteroy v. United States","cite":"413 A.2d 1294","y":1980,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/413/1294/","by":{"1":"28","2":"20"}},{"t":"case","label":"George v. McDonough","cite":"596 U.S. 740","y":2022,"id":"2021/21-234","sc":1,"op":3,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Mathis v. United States","cite":"579 U.S. 500","y":2016,"id":"2015/15-6092","sc":1,"op":2,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Miles v. Apex Marine Corp.","cite":"498 U.S. 19","y":1990,"id":"1990/89-1158","sc":1,"sum":"Petitioner Miles, the mother and administratrix of the estate of a seaman killed by a fellow crew member aboard the vessel of respondents (collectively Apex) docked in an American port, sued Apex in District Court, alleging negligence under the Jones Act for failure to prevent the assault, and breach of the warranty of seaworthiness under general maritime law for hiring a crew member unfit to serve. After the court …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"People v. Beardsley","cite":"113 N.W. 1128","y":1907,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./113/1128/","by":{"1":"25"}},{"t":"case","label":"People v. Best","cite":"609 N.Y.S.2d 478","y":1994,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/N.Y.S.2d/609/478/","op":1,"by":{"1":"43"}},{"t":"case","label":"Quarles v. United States","cite":"587 U.S. 645","y":2019,"id":"2018/17-778","sc":1,"op":1,"sum":"Michigan’s third-degree home-invasion statute substantially corresponds to or is narrower than generic burglary for purposes of qualifying for enhanced sentencing under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Shular v. United States","cite":"589 U.S. 154","y":2020,"id":"2019/18-6662","sc":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"State v. Barnes","cite":"212 S.W. 100","y":1919,"court":"Tenn.","url":"https://www.courtlistener.com/c/S.W./212/100/","by":{"1":"28","2":"20"}},{"t":"case","label":"State v. Evangelista","cite":"353 S.E.2d 375","y":1987,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E.2d/353/375/","by":{"1":"28"}},{"t":"case","label":"State v. Miranda","cite":"878 A.2d 1118","y":2005,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/878/1118/","by":{"1":"28","2":"19"}},{"t":"case","label":"State v. Smith","cite":"65 Me. 257","y":1876,"url":"https://www.courtlistener.com/c/Me./65/257/","by":{"1":"25, 28","2":"20"}},{"t":"case","label":"State v. Spates","cite":"405 A.2d 656","y":1978,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/405/656/","by":{"1":"28","2":"20"}},{"t":"case","label":"State v. Staples","cite":"148 N.W. 283","y":1914,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./148/283/","by":{"1":"28"}},{"t":"case","label":"State v. Valley","cite":"571 A.2d 579","y":1989,"court":"Vt.","url":"https://www.courtlistener.com/c/A.2d/571/579/","by":{"1":"28","2":"20"}},{"t":"case","label":"State v. Williquette","cite":"385 N.W.2d 145","y":1986,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/385/145/","by":{"1":"28","2":"20"}},{"t":"case","label":"Sykes v. United States","cite":"564 U.S. 1","y":2011,"id":"2010/09-11311","sc":1,"sum":"The Court held that a conviction for resisting arrest counts as a violent felony under the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Territory v. Manton","cite":"19 P. 387","y":1888,"court":"Mont.","url":"https://www.courtlistener.com/c/P./19/387/","op":1,"ar":1,"by":{"1":"24, 25","2":"7"}},{"t":"case","label":"United States v. Báez-Martínez","cite":"950 F.3d 119","y":2020,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/950/119/","by":{"1":"17"}},{"t":"case","label":"United States v. Bowers","cite":"2022 WL 17718686","y":2022,"court":"W.D. Pa. Dec. 15","by":{"1":"41, 42"}},{"t":"case","label":"United States v. Christie","cite":"717 F.3d 1156","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/717/1156/","by":{"1":"31"}},{"t":"case","label":"United States v. Keene","cite":"955 F.3d 391","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/955/391/","by":{"1":"7"}},{"t":"case","label":"United States v. Mayo","cite":"90 F.3d 218","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/90/218/","by":{"1":"41"}},{"t":"case","label":"United States v. Ortiz-Orellana","cite":"901 F.4th 689","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/901/689/","by":{"1":"42"}},{"t":"case","label":"United States v. Rodriguez-Moreno","cite":"526 U.S. 275","y":1999,"id":"1998/97-1139","sc":1,"sum":"The Court held that \"[v]enue in a prosecution for using or carrying a firearm 'during and in relation to any crime of violence' in violation of section 924(c)(1) is proper in any district where the crime of violence was committed.\" Justice Thomas wrote for the Court that, \"A kidnapping...does not end until the victim is free.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Zessman v. State","cite":"573 P.2d 1174","y":1978,"court":"Nev.","url":"https://www.courtlistener.com/c/P.2d/573/1174/","by":{"1":"28"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(e)(2)(B)","(e)(2)(B)(i)","(c)(1)(1994)","(c)(1)(A)","(c)(1)(A)(i)","(c)(3)(A)","(c)(3)(B)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"1":"29, 5, 5, 38, 42, 42, 42, 42, 42"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)(F)"],"by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","subs":["(d)"],"by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 249","url":"https://www.law.cornell.edu/uscode/text/18/249","subs":["(a)(1)","(a)(1)(B)"],"stext":{"head":"§249. Hate crime acts","paras":[[0,"(a) In General.—"],[1,"(1) Offenses involving actual or perceived race, color, religion, or national origin.—Whoever, whether or not acting under color of law, willfully causes bodily injury to any person or, through the use of fire, a firearm, a dangerous weapon, or an explosive or incendiary device, attempts to cause bodily injury to any person, because of the actual or perceived race, color, religion, or national origin of any person—"],[2,"(A) shall be imprisoned not more than 10 years, fined in accordance with this title, or both; and"],[2,"(B) shall be imprisoned for any term of years or for life, fined in accordance with this title, or both, if—"],[3,"(i) death results from the offense; or"],[3,"(ii) the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill."],[1,"(2) Offenses involving actual or perceived religion, national origin, gender, sexual orientation, gender identity, or disability.—"],[2,"(A) In general.—Whoever, whether or not acting under color of law, in any circumstance described in subparagraph (B) or paragraph (3), willfully causes bodily injury to any person or, through the use of fire, a firearm, a dangerous weapon, or an explosive or incendiary device, attempts to cause bodily injury to any person, because of the actual or perceived religion, national origin, gender, sexual orientation, gender identity, or disability of any person—"],[3,"(i) shall be imprisoned not more than 10 years, fined in accordance with this title, or both; and"],[3,"(ii) shall be imprisoned for any term of years or for life, fined in accordance with this title, or both, if—"],[4,"(I) death results from the offense; or"],[4,"(II) the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill."],[2,"(B) Circumstances described.—For purposes of subparagraph (A), the circumstances described in this subparagraph are that—"],[3,"(i) the conduct described in subparagraph (A) occurs during the course of, or as the result of, the travel of the defendant or the victim—"],[4,"(I) across a State line or national border; or"],[4,"(II) using a channel, facility, or instrumentality of interstate or foreign commerce;"],[3,"(ii) the defendant uses a channel, facility, or instrumentality of interstate or foreign commerce in connection with the conduct described in subparagraph (A);"],[3,"(iii) in connection with the conduct described in subparagraph (A), the defendant employs a firearm, dangerous weapon, explosive or incendiary device, or other weapon that has traveled in interstate or foreign commerce; or"],[3,"(iv) the conduct described in subparagraph (A)—"],[4,"(I) interferes with commercial or other economic activity in which the victim is engaged at the time of the conduct; or"],[4,"(II) otherwise affects interstate or foreign commerce."],[1,"(3) Offenses occurring in the special maritime or territorial jurisdiction of the united states.—Whoever, within the special maritime or territorial jurisdiction of the United States, engages in conduct described in paragraph (1) or in paragraph (2)(A) (without regard to whether that conduct occurred in a circumstance described in paragraph (2)(B)) shall be subject to the same penalties as prescribed in those paragraphs."],[1,"(4) Guidelines.—All prosecutions conducted by the United States under this section shall be undertaken pursuant to guidelines issued by the Attorney General, or the designee of the Attorney General, to be included in the United States Attorneys' Manual that shall establish neutral and objective criteria for determining whether a crime was committed because of the actual or perceived status of any person."],[1,"(5) Lynching.—Whoever conspires to commit any offense under paragraph (1), (2), or (3) shall, if death or serious bodily injury (as defined in section 2246 of this title) results from the offense, be imprisoned for not more than 30 years, fined in accordance with this title, or both."],[1,"(6) Other conspiracies.—Whoever conspires to commit any offense under paragraph (1), (2), or (3) shall, if death or serious bodily injury (as defined in section 2246 of this title) results from the offense, or if the offense includes kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill, be imprisoned for not more than 30 years, fined in accordance with this title, or both."],[0,"(b) Certification Requirement.—"],[1,"(1) In general.—No prosecution of any offense described in this subsection may be undertaken by the United States, except under the certification in writing of the Attorney General, or a designee, that—"],[2,"(A) the State does not have jurisdiction;"],[2,"(B) the State has requested that the Federal Government assume jurisdiction;"],[2,"(C) the verdict or sentence obtained pursuant to State charges left demonstratively unvindicated the Federal interest in eradicating bias-motivated violence; or"],[2,"(D) a prosecution by the United States is in the public interest and necessary to secure substantial justice."],[1,"(2) Rule of construction.—Nothing in this subsection shall be construed to limit the authority of Federal officers, or a Federal grand jury, to investigate possible violations of this section."],[0,"(c) Definitions.—In this section—"],[1,"(1) the term \"bodily injury\" has the meaning given such term in section 1365(h)(4) of this title, but does not include solely emotional or psychological harm to the victim;"],[1,"(2) the term \"explosive or incendiary device\" has the meaning given such term in section 232 of this title;"],[1,"(3) the term \"firearm\" has the meaning given such term in section 921(a) of this title;"],[1,"(4) the term \"gender identity\" means actual or perceived gender-related characteristics; and"],[1,"(5) the term \"State\" includes the District of Columbia, Puerto Rico, and any other territory or possession of the United States."],[0,"(d) Statute of Limitations.—"],[1,"(1) Offenses not resulting in death.—Except as provided in paragraph (2), no person shall be prosecuted, tried, or punished for any offense under this section unless the indictment for such offense is found, or the information for such offense is instituted, not later than 7 years after the date on which the offense was committed."],[1,"(2) Death resulting offenses.—An indictment or information alleging that an offense under this section resulted in death may be found or instituted at any time without limitation."],[0,"(e) Supervised Release.—If a court includes, as a part of a sentence of imprisonment imposed for a violation of subsection (a), a requirement that the defendant be placed on a term of supervised release after imprisonment under section 3583, the court may order, as an explicit condition of supervised release, that the defendant undertake educational classes or community service directly related to the community harmed by the defendant's offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/249?type=usc&year=mostrecent&link-type=html"},"head":"§249. Hate crime acts","tname":"Crimes and Criminal Procedure","by":{"1":"41","2":"21"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(33)(A)(2012)","(a)(33)(A)(ii)(2012)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§921. Definitions","tname":"Crimes and Criminal Procedure","by":{"1":"32, 15"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(2012)","(g)(9)(2012)","(g)(9)"],"by":{"1":"32, 32, 5-8, 12, 13, 18, 27-30, 33, 40-42, 44-47"}},{"t":"usc","label":"18 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/18/1111","stext":{"head":"§1111. Murder","paras":[[0,"(a) Murder is the unlawful killing of a human being with malice aforethought. Every murder perpetrated by poison, lying in wait, or any other kind of willful, deliberate, malicious, and premeditated killing; or committed in the perpetration of, or attempt to perpetrate, any arson, escape, murder, kidnapping, treason, espionage, sabotage, aggravated sexual abuse or sexual abuse, child abuse, burglary, or robbery; or perpetrated as part of a pattern or practice of assault or torture against a child or children; or perpetrated from a premeditated design unlawfully and maliciously to effect the death of any human being other than him who is killed, is murder in the first degree."],[0,"Any other murder is murder in the second degree."],[0,"(b) Within the special maritime and territorial jurisdiction of the United States,"],[0,"Whoever is guilty of murder in the first degree shall be punished by death or by imprisonment for life;"],[0,"Whoever is guilty of murder in the second degree, shall be imprisoned for any term of years or for life."],[0,"(c) For purposes of this section—"],[1,"(1) the term \"assault\" has the same meaning as given that term in section 113;"],[1,"(2) the term \"child\" means a person who has not attained the age of 18 years and is—"],[2,"(A) under the perpetrator's care or control; or"],[2,"(B) at least six years younger than the perpetrator;"],[1,"(3) the term \"child abuse\" means intentionally or knowingly causing death or serious bodily injury to a child;"],[1,"(4) the term \"pattern or practice of assault or torture\" means assault or torture engaged in on at least two occasions;"],[1,"(5) the term \"serious bodily injury\" has the meaning set forth in section 1365; and"],[1,"(6) the term \"torture\" means conduct, whether or not committed under the color of law, that otherwise satisfies the definition set forth in section 2340(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1111?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1111. Murder","tname":"Crimes and Criminal Procedure","by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 1112","url":"https://www.law.cornell.edu/uscode/text/18/1112","subs":["(a)"],"by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 1513","url":"https://www.law.cornell.edu/uscode/text/18/1513","subs":["(b)"],"by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 1955","url":"https://www.law.cornell.edu/uscode/text/18/1955","by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 1958","url":"https://www.law.cornell.edu/uscode/text/18/1958","by":{"1":"3, 5"}},{"t":"usc","label":"18 U.S.C. § 1959","url":"https://www.law.cornell.edu/uscode/text/18/1959","subs":["(a)(5)"],"stext":{"head":"§1959. Violent crimes in aid of racketeering activity","paras":[[0,"(a) Whoever, as consideration for the receipt of, or as consideration for a promise or agreement to pay, anything of pecuniary value from an enterprise engaged in racketeering activity, or for the purpose of gaining entrance to or maintaining or increasing position in an enterprise engaged in racketeering activity, murders, kidnaps, maims, assaults with a dangerous weapon, commits assault resulting in serious bodily injury upon, or threatens to commit a crime of violence against any individual in violation of the laws of any State or the United States, or attempts or conspires so to do, shall be punished—"],[1,"(1) for murder, by death or life imprisonment, or a fine under this title, or both; and for kidnapping, by imprisonment for any term of years or for life, or a fine under this title, or both;"],[1,"(2) for maiming, by imprisonment for not more than thirty years or a fine under this title, or both;"],[1,"(3) for assault with a dangerous weapon or assault resulting in serious bodily injury, by imprisonment for not more than twenty years or a fine under this title, or both;"],[1,"(4) for threatening to commit a crime of violence, by imprisonment for not more than five years or a fine under this title, or both;"],[1,"(5) for attempting or conspiring to commit murder or kidnapping, by imprisonment for not more than ten years or a fine under this title, or both; and"],[1,"(6) for attempting or conspiring to commit a crime involving maiming, assault with a dangerous weapon, or assault resulting in serious bodily injury, by imprisonment for not more than three years or a fine of 1 under this title, or both."],[0,"(b) As used in this section—"],[1,"(1) \"racketeering activity\" has the meaning set forth in section 1961 of this title; and"],[1,"(2) \"enterprise\" includes any partnership, corporation, association, or other legal entity, and any union or group of individuals associated in fact although not a legal entity, which is engaged in, or the activities of which affect, interstate or foreign commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1959?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1959. Violent crimes in aid of racketeering activity","tname":"Crimes and Criminal Procedure","by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/18/3142","subs":["(g)"],"by":{"1":"27"}},{"t":"case","label":"Avellaneda v. State","cite":"496 S.W.3d 311","y":2016,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.3d/496/311/","by":{"2":"19"}},{"t":"case","label":"Bradley v. United States","cite":"856 A.2d 1157","y":2004,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/856/1157/","by":{"2":"19"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"581 U.S. 385","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"State v. Small","cite":"100 So.3d 797","y":2012,"court":"La.","url":"https://www.courtlistener.com/c/So.3d/100/797/","by":{"2":"19"}},{"t":"case","label":"State v. Sudberry","cite":"2012 WL 5544611","y":2012,"court":"Tenn. Crim. App. Nov. 14","by":{"2":"20"}},{"t":"case","label":"United States v. Harris","cite":"88 F.4th 458","y":2023,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/88/458/","by":{"2":"9"}},{"t":"law","label":"Pub. L. No. 111-84","url":"https://www.govinfo.gov/link/plaw/111/public/84","by":{"2":"21"}}]};